import 'dart:io';
import 'package:flutter/material.dart';
import '../core/theme_controller.dart';
import '../database/db_helper.dart';
class DashboardScreen extends StatefulWidget{final AppThemeController theme;const DashboardScreen({super.key,required this.theme});@override State<DashboardScreen> createState()=>_DashboardState();}
class _DashboardState extends State<DashboardScreen>{int birds=0,active=0,cycles=0,eggs=0;@override void initState(){super.initState();load();}Future<void>load()async{final d=await DBHelper.db;final a=await d.rawQuery("SELECT COUNT(*) n FROM aves");final ac=await d.rawQuery("SELECT COUNT(*) n FROM aves WHERE status='ATIVA'");final c=await d.rawQuery('SELECT COUNT(*) n FROM ciclos WHERE status != \'FINALIZADO\'');final e=await d.rawQuery('SELECT COUNT(*) n FROM ovos');setState((){birds=(a.first['n']as int);active=ac.first['n']as int;cycles=c.first['n']as int;eggs=e.first['n']as int;});}Widget card(String t,String v,IconData icon)=>Expanded(child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,size:26),const SizedBox(height:10),Text(v,style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text(t)]))));@override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(16,42,16,24),children:[Row(children:[if(widget.theme.logoPath!=null)CircleAvatar(backgroundImage:FileImage(File(widget.theme.logoPath!)),radius:28),if(widget.theme.logoPath!=null)const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.theme.houseName.isEmpty?'Meu Canaril':widget.theme.houseName,style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),Text('${widget.theme.breederName} · ${widget.theme.city}-${widget.theme.state}')]))]),const SizedBox(height:24),Row(children:[card('Aves cadastradas','$birds',Icons.flutter_dash),const SizedBox(width:10),card('Aves ativas','$active',Icons.verified)]),const SizedBox(height:10),Row(children:[card('Ciclos abertos','$cycles',Icons.favorite),const SizedBox(width:10),card('Ovos registrados','$eggs',Icons.egg)]),const SizedBox(height:18),Card(child:ListTile(leading:CircleAvatar(backgroundColor:widget.theme.primary,child:Icon(Icons.auto_awesome,color:widget.theme.onPrimary)),title:const Text('Identidade visual automática'),subtitle:const Text('A interface usa as cores extraídas da logo do seu canaril.'))),const SizedBox(height:10),Card(child:ListTile(leading:const Icon(Icons.storage),title:const Text('Banco local SQLite'),subtitle:const Text('Projetado para milhares de aves, histórico e genealogia sem depender de internet.')))]));}
